#[test]
fn historical_quantified_no_inventory_is_not_capacity() {
    let mut state = RemoteCoordinatorState::default();
    let mut worker = fixture_worker_registration();
    worker.concurrency = 64;
    assert!(worker.resource_inventory.is_none());
    apply_worker_registration(&mut state, worker).expect("worker registers without capacity inventory");
    let before = state.clone();
    let mut request = fixture_quantified_coordinator_request("historical-demand", "historical-demand-claim");
    request.wait_for_worker = true;
    println!("historical-request={}", serde_json::to_string(&request).unwrap());
    for round in 0..3 {
        let decision = admit_fixture_dispatch(&mut state, &request).expect("valid quantified request");
        assert_eq!(decision, RemoteCoordinatorDispatchDecision::Pending {
            reason: "remote-worker-resource-inventory-missing".to_string(),
        });
        assert_eq!(state, before);
        assert!(state.jobs.is_empty());
        assert!(state.resource_leases.is_empty());
        println!("round={round} blocker=remote-worker-resource-inventory-missing jobs=0 leases=0 demand-contract=absent");
    }
    request.wait_for_worker = false;
    assert_eq!(admit_fixture_dispatch(&mut state, &request).unwrap(),
        RemoteCoordinatorDispatchDecision::Reject {
            reason: "remote-worker-resource-inventory-missing".to_string(),
        });
    assert_eq!(state, before);
}
